/** 
 * Subscribes to presence updates for specified contact identifier.
 * @param parent contact group
 * @param contactIdentifier contact
 * @throws OperationFailedException if not implemented
 * @throws IllegalArgumentException on bad input
 * @throws IllegalStateException if disconnected
 */
@Override public void subscribe(final ContactGroup parent,final String contactIdentifier) throws IllegalArgumentException, IllegalStateException, OperationFailedException {
  if (contactIdentifier == null) {
    throw new IllegalArgumentException("contactIdentifier cannot be null");
  }
  final IrcConnection connection=this.parentProvider.getIrcStack().getConnection();
  if (connection == null) {
    return;
  }
  try {
    connection.getPresenceManager().addNickWatch(contactIdentifier);
  } catch (UnsupportedOperationException | ClassCastException | NullPointerException e) {
    throw new OperationFailedException("Failed to add nick watch", e);
  }
}
